//
//  LiveActivityIntentLink.swift
//  DSH-Mizar
//
//  Keep the Live Activity button intents in the app binary.
//
//  The buttons are declared by the widget extension, so the extension's object
//  files contain `AllowOnceIntent` and `RejectIntent`. The app and the extension
//  share MizarKit, but a static library only links the object files something
//  references: the app target does not otherwise name either intent, so the
//  linker dead-strips their implementations from the app. App Intents metadata
//  is generated by scanning the module rather than by reading the linked
//  symbols, so the metadata still advertises both actions in the app -- and the
//  system picks the app to perform them. What the operator sees is a Lock
//  Screen button that does nothing, and the system log says
//  `LNContextErrorDomain` 2002 because the app has no `perform()` to run.
//
//  A plain `_ = AllowOnceIntent.self` in the app's `init()` is not enough: the
//  compiler may fold an unused type reference away before the linker sees it.
//  A runtime-initialized array of the intent types is a real reference, and the
//  app's `init()` reads it so the initializer cannot be optimized out.
//

import AppIntents
import MizarKit

enum LiveActivityIntentLink {
    /// Both intents, as existentials: constructing this array needs their type
    /// metadata, and the metadata carries their App Intents conformance.
    static let types: [any AppIntent.Type] = [
        AllowOnceIntent.self,
        RejectIntent.self,
    ]
}
